import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"添加和管理组织用户","description":"组织管理员添加用户、分配角色、编辑资料、重置密码，并核对操作结果。","frontmatter":{"title":"添加和管理组织用户","description":"组织管理员添加用户、分配角色、编辑资料、重置密码，并核对操作结果。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/users.md","filePath":"zh/使用指南/添加和管理组织用户.md"}'),o={name:"zh/guide/users.md"};function i(l,t,n,h,s,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="添加和管理组织用户" tabindex="-1">添加和管理组织用户 <a class="header-anchor" href="#添加和管理组织用户" aria-label="Permalink to &quot;添加和管理组织用户&quot;">​</a></h1><p>本页由<strong>组织管理员</strong>从公共入口操作。这里管理的是进入该组织工作台的账号；工程页面自己的登录账号是另一层身份，见<a href="/induframe-docs/zh/concepts/development-and-runtime.html">开发、发布与运行</a>。</p><h2 id="_1-打开用户管理" tabindex="-1">1. 打开用户管理 <a class="header-anchor" href="#_1-打开用户管理" aria-label="Permalink to &quot;1. 打开用户管理&quot;">​</a></h2><p>从公共入口登录自己的组织，进入 <strong>“用户管理”</strong>。看不到该入口时，先核对当前组织和角色，不要改用别人的账号尝试。</p><p>可按用户名或姓名搜索，按角色和状态筛选。没有找到用户时，先清除筛选、核对当前页和组织，再判断是否需要重新添加。</p><h2 id="_2-添加用户并选择角色" tabindex="-1">2. 添加用户并选择角色 <a class="header-anchor" href="#_2-添加用户并选择角色" aria-label="Permalink to &quot;2. 添加用户并选择角色&quot;">​</a></h2><p>点击 <strong>“添加用户”</strong>，填写：</p><table tabindex="0"><thead><tr><th>字段</th><th>应填写什么</th></tr></thead><tbody><tr><td>用户名</td><td>用户以后登录时输入的名称；保存后不能在编辑面板直接改名</td></tr><tr><td>密码</td><td>通过安全方式交付的临时密码，不使用公开示例或共享密码</td></tr><tr><td>角色</td><td>按实际职责选下面三类角色之一</td></tr></tbody></table><table tabindex="0"><thead><tr><th>角色</th><th>主要用途</th></tr></thead><tbody><tr><td>管理员</td><td>维护本组织用户和管理设置</td></tr><tr><td>工程人员</td><td>创建、配置和开发有权限的工程</td></tr><tr><td>运维人员</td><td>处理有权限的工程与运行、节点相关工作</td></tr></tbody></table><p>角色和具体工程的可见范围共同决定可做什么，不代表拥有其他组织的权限。没有用户管理职责时，不要只为方便而分配“管理员”。</p><p>“高级资料（选填）”中的姓名、邮箱、电话等按需要填写。自定义属性用于补充资料，不能代替角色或权限设置。</p><p>提交创建，等到成功提示后核对列表，再刷新确认用户仍在。新用户首次使用临时密码登录时，如进入修改初始密码页面，应先修改再继续工作。</p><h2 id="_3-编辑资料或调整状态" tabindex="-1">3. 编辑资料或调整状态 <a class="header-anchor" href="#_3-编辑资料或调整状态" aria-label="Permalink to &quot;3. 编辑资料或调整状态&quot;">​</a></h2><p>在用户行点击 <strong>“编辑”</strong>，修改资料、角色或状态后保存，再核对列表。</p><ul><li>用户名在编辑面板中不可改。</li><li>状态有“活跃”“未激活”“暂停”等选项；暂停使用前先通知本人。</li><li>当前管理员不能在这里修改自己的角色或状态。</li><li>系统对管理员保留和账号权限有保护，出现拒绝提示时先核实，不反复提交。</li></ul><p>修改角色或停用用户会影响原有访问。修改后让本人按页面提示重新登录、核对可访问内容。</p><h2 id="_4-用户忘记密码时" tabindex="-1">4. 用户忘记密码时 <a class="header-anchor" href="#_4-用户忘记密码时" aria-label="Permalink to &quot;4. 用户忘记密码时&quot;">​</a></h2><ol><li>核对组织和用户，点击该行 <strong>“重置密码”</strong>。</li><li>输入新密码和确认密码，两次一致。</li><li>提交 <strong>“重置”</strong>，等待“密码重置成功”。</li><li>通过安全方式单独交付密码，并提醒用户按首次登录提示改密。</li></ol><p>建议使用 8–72 个英文字母、数字或半角符号。不要把密码写在普通工单、截图、公开文档或群消息里。</p><h2 id="_5-删除用户前先确认" tabindex="-1">5. 删除用户前先确认 <a class="header-anchor" href="#_5-删除用户前先确认" aria-label="Permalink to &quot;5. 删除用户前先确认&quot;">​</a></h2><p>优先判断是否只需要暂停账号。确定删除时，在用户行点击“删除”，核对确认框里的用户名，再点击 <strong>“确定删除”</strong>；不确定时取消。</p><p>删除不可恢复。若页面拒绝删除或提示管理员保护，应交由合适的管理员处理，不更换身份绕过限制。</p><h2 id="怎样确认完成" tabindex="-1">怎样确认完成 <a class="header-anchor" href="#怎样确认完成" aria-label="Permalink to &quot;怎样确认完成&quot;">​</a></h2><p>确认保存或重置成功，刷新后列表内容正确，并让用户从正确组织入口验证登录。失败时记录提示和操作对象，不连续重复添加同名用户。</p><p>下一步：<a href="/induframe-docs/zh/guide/projects.html">创建和管理工程</a> · <a href="/induframe-docs/zh/guide/login.html">日常登录与退出</a>。</p>',25)])])}const u=a(o,[["render",i]]);export{c as __pageData,u as default};
